{{ af.button('', 'submit', af_skin('button', 'outline', 'w-full'), {}, af_esc(l.deny ?? '')) }}{%- endset -%}
{{ af.form(p.action ?? '', 'flex-1', {'data-testid': 'deny'}, c5) }}
{%- set c6 -%}{{ af.hidden('csrf', p.csrf ?? '') }}
{{ af.hidden('decision', 'approve') }}
{{ af.button('', 'submit', af_skin('button', 'default', 'w-full'), {}, af_esc(l.approve ?? '')) }}{%- endset -%}
{{ af.form(p.action ?? '', 'flex-1', {'data-testid': 'approve'}, c6) }}{%- endset -%}{{ af.group('2', '', 'between', '', {}, c7) }}
